import{_ as n,l as s,o as e,c as i,v as o,p as l,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"正则匹配与回溯爆炸","description":"","frontmatter":{"title":"正则匹配与回溯爆炸","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/regex-backtracking.md","filePath":"cs/regex-backtracking.md","lastUpdated":1789023840000}'),p={name:"cs/regex-backtracking.md"};function m(A,a,_,u,T,f){const t=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="正则匹配与回溯爆炸" tabindex="-1">正则匹配与回溯爆炸 <a class="header-anchor" href="#正则匹配与回溯爆炸" aria-label="Permalink to &quot;正则匹配与回溯爆炸&quot;">​</a></h1><div class="epigraph"><p>正则对应 NFA，可线性于文本；回溯实现在嵌套 `*` 上可指数，ReDoS 是算法选择不是语言必然。</p><footer>—— 据 Thompson, Regular Expression Search Algorithm, 1968；Aho, Sethi, Ullman 龙书；[Chomsky](/cs/chomsky-hierarchy) 对照整理</footer></div><p>上一课<a href="/cs/lyndon-duval">Lyndon 分解</a>收束线性串技法。正则匹配在主干词法会再遇。本课缺口是<strong>复杂度</strong>：Thompson NFA 模拟 \\(O(nm)\\)，回溯引擎最坏指数。不重写正则→NFA 全构造。后课平面几何。线性串课序在此结束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正则语言可用 NFA，文本长 \\(n\\)、表达式长 \\(m\\)，Thompson 模拟 \\(O(nm)\\)。POSIX/Perl 回溯：每个 <code>*</code> 分叉，<code>a?^n a^n</code> 一类使路径指数。恶意正则 + 文本 = ReDoS。捕获组、回溯引用超出正则，更难。</p><p>缺口是实现模型，不是泵引理。</p><h3 id="不是「正则很慢」" tabindex="-1">不是「正则很慢」 <a class="header-anchor" href="#不是「正则很慢」" aria-label="Permalink to &quot;不是「正则很慢」&quot;">​</a></h3><p>语言类是正则，算法可以是 NFA。慢来自回溯实现。不要把正则语言判成 NPC。</p><p><span class="marginnote">Thompson 1968。Russ Cox 对回溯 vs NFA 的工程论述广泛引用。龙书词法扫描。后课凸包换几何。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>要最坏线性：Thompson NFA 或 DFA（DFA 可能 \\(2^m\\) 状态）。需要回溯特性才用回溯，并限制或超时。诊断：嵌套量词 + 长失败文本。</p>',11)),(e(),l(h,null,{default:r(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RE%5B%22%E6%AD%A3%E5%88%99%22%5D%20--%3E%20NFA%5B%22Thompson%20NFA%20O(nm)%22%5D%0A%20%20RE%20--%3E%20BT%5B%22%E5%9B%9E%E6%BA%AF%EF%BC%9A%E6%9C%80%E5%9D%8F%E6%8C%87%E6%95%B0%22%5D%0A%20%20BT%20--%3E%20REDOS%5B%22ReDoS%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>DFA 最小化接<a href="/cs/dfa-minimization">DFA 最小化</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NFA 位集或列表模拟：当前位置集合，每字符扫边。回溯是 DFS 这条 NFA，最坏走遍路径。与 CYK：上下文无关才 \\(O(n^3)\\)。与 KMP：单模式无 <code>*</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 PCRE 全语义。不写递归正则。后课默认：最坏要线性用 NFA；回溯当工程风险。下一课凸包 Graham / Andrew。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正则语言可 \\(O(nm)\\) NFA。</li><li>回溯实现可指数，ReDoS。</li><li>超正则特征另计代价。</li><li>出处：Thompson, 1968；龙书。</li></ul>',7))])}const F=n(p,[["render",m]]);export{E as __pageData,F as default};
